changeSet.sql:
-- All mappings are materialized and validated before the first clinical write. CREATE TEMP TABLE amr_program_canonical ON COMMIT DROP AS SELECT id, CASE WHEN upper(trim(name)) = 'MICROBIOLOGY' THEN min(id) OVER (PARTITION BY upper(trim(name)), domain) ELSE id END AS canonical_id FROM clinlims.program;
DO $$ BEGIN IF EXISTS ( SELECT 1 FROM clinlims.program a JOIN amr_program_canonical m ON m.id=a.id JOIN clinlims.program b ON b.id=m.canonical_id WHERE a.id<>b.id AND (a.questionnaire_fhir_uuid IS DISTINCT FROM b.questionnaire_fhir_uuid OR a.is_active IS DISTINCT FROM b.is_active OR EXISTS ((SELECT test_section_id FROM clinlims.program_lab_unit WHERE program_id=a.id EXCEPT SELECT test_section_id FROM clinlims.program_lab_unit WHERE program_id=b.id) UNION ALL (SELECT test_section_id FROM clinlims.program_lab_unit WHERE program_id=b.id EXCEPT SELECT test_section_id FROM clinlims.program_lab_unit WHERE program_id=a.id)))) THEN RAISE EXCEPTION 'AMR migration: duplicate Microbiology Programs differ; reconcile their questions and lab units first'; END IF; END $$;
CREATE TEMP TABLE amr_case_map ON COMMIT DROP AS SELECT c.id, coalesce(c.sample_id, si.samp_id) sample_id, coalesce(c.sample_type_id, si.typeosamp_id) sample_type_id, coalesce(c.lab_unit_id, route.unit_id) lab_unit_id, coalesce(existing.canonical_id, mapped.program_id) program_id, route.unit_count, mapped.program_count, c.workflow_type, c.lab_unit_id IS NULL needs_unit, c.program_id IS NULL needs_program FROM clinlims.micro_case c LEFT JOIN clinlims.sample_item si ON si.id=c.sample_item_id LEFT JOIN amr_program_canonical existing ON existing.id=c.program_id LEFT JOIN LATERAL ( SELECT min(t.test_section_id) unit_id, count(DISTINCT t.test_section_id) unit_count FROM clinlims.micro_case_analysis ca JOIN clinlims.analysis a ON a.id=ca.analysis_id JOIN clinlims.test t ON t.id=a.test_id WHERE ca.case_id=c.id ) route ON true LEFT JOIN LATERAL ( SELECT min(m.canonical_id) program_id, count(DISTINCT m.canonical_id) program_count FROM clinlims.program p JOIN amr_program_canonical m ON m.id=p.id WHERE p.is_active='Y' AND upper(p.domain)='CLINICAL' AND ( (c.workflow_type='BACTERIOLOGY' AND upper(trim(p.code)) IN ('BACTERIOLOGY','MICROBIOLOGY')) OR (c.workflow_type='MYCOBACTERIOLOGY_TB' AND upper(trim(p.code)) IN ('TB','MYCOBACTERIOLOGY_TB')) OR (c.workflow_type='MYCOLOGY' AND upper(trim(p.code))='MYCOLOGY')) ) mapped ON true;
DO $$ DECLARE bad text; BEGIN SELECT string_agg(id, ', ' ORDER BY id) INTO bad FROM amr_case_map WHERE sample_id IS NULL OR sample_type_id IS NULL OR lab_unit_id IS NULL OR (needs_unit AND unit_count<>1) OR (needs_program AND workflow_type IS NOT NULL AND (program_id IS NULL OR program_count<>1)); IF bad IS NOT NULL THEN RAISE EXCEPTION 'AMR migration: ambiguous or missing order, sample type, test-routing lab unit or Program for cases: %', bad; END IF; IF EXISTS (SELECT 1 FROM amr_case_map m JOIN clinlims.micro_case_analysis ca ON ca.case_id=m.id JOIN clinlims.analysis a ON a.id=ca.analysis_id JOIN clinlims.sample_item si ON si.id=a.sampitem_id WHERE si.samp_id<>m.sample_id) THEN RAISE EXCEPTION 'AMR migration: a legacy case contains analyses from different orders'; END IF; END $$;

UPDATE clinlims.micro_case c SET culture_purpose = CASE
    WHEN c.site_id IS NOT NULL THEN 'ROUTINE_MONITORING'
    WHEN EXISTS (SELECT 1 FROM clinlims.micro_case_order_detail d
        WHERE d.case_id = c.id AND d.culture_purpose = 'ACTIVE_SCREENING') THEN 'SCREENING'
    ELSE 'DIAGNOSTIC' END;
ALTER TABLE clinlims.micro_case ADD CONSTRAINT micro_case_purpose_valid CHECK
    (culture_purpose IN ('DIAGNOSTIC','SCREENING','TREATMENT_FOLLOW_UP','SURVEY_OR_STUDY',
     'EQA_PROFICIENCY','ROUTINE_MONITORING','POST_CLEANING_CHECK','OUTBREAK_INVESTIGATION','COMPLAINT'));
ALTER TABLE clinlims.sample ADD CONSTRAINT micro_replicate_count_valid CHECK
    (microbiology_replicate_count BETWEEN 1 AND 999);

INSERT INTO clinlims.micro_case_activity(id,case_id,activity_type,occurred_at,performed_by,note,structured_data) SELECT md5('M8-assignment-'||c.id),c.id,'MIGRATION_REVIEW',now(),NULL, 'Legacy case mapped to a laboratory unit and Program; administrator review required', json_build_object('reason','LEGACY_ASSIGNMENT','workflow',m.workflow_type,'labUnitId',m.lab_unit_id, 'programId',m.program_id,'previousLabUnitId',c.lab_unit_id,'previousProgramId',c.program_id)::text FROM clinlims.micro_case c JOIN amr_case_map m ON m.id=c.id WHERE m.needs_unit OR (m.needs_program AND m.workflow_type IS NOT NULL);
UPDATE clinlims.micro_case c SET sample_id=m.sample_id, sample_type_id=m.sample_type_id, lab_unit_id=m.lab_unit_id, program_id=m.program_id, status=coalesce(c.status,CASE WHEN c.stage='REJECTED' THEN 'REJECTED' ELSE 'ACTIVE' END) FROM amr_case_map m WHERE m.id=c.id;
INSERT INTO clinlims.micro_case_sample(id,case_id,sample_item_id,joined_at,joined_by) SELECT md5('M8-member-'||members.case_id||'-'||members.sample_item_id),members.case_id,members.sample_item_id, c.created_at,coalesce(c.created_by,'MIGRATION') FROM (SELECT id case_id,sample_item_id FROM clinlims.micro_case WHERE sample_item_id IS NOT NULL UNION SELECT ca.case_id,a.sampitem_id FROM clinlims.micro_case_analysis ca JOIN clinlims.analysis a ON a.id=ca.analysis_id) members JOIN clinlims.micro_case c ON c.id=members.case_id WHERE NOT EXISTS (SELECT 1 FROM clinlims.micro_case_sample ms WHERE ms.case_id=members.case_id AND ms.sample_item_id=members.sample_item_id AND ms.split_out_at IS NULL);
UPDATE clinlims.micro_case_analysis ca SET case_role=coalesce(ca.case_role,'DIRECT'), placement=coalesce(ca.placement,'INITIAL'),collected_in_sets=coalesce(ca.collected_in_sets,false); UPDATE clinlims.test SET opens_microbiology_case=true,microbiology_case_role='CULTURE' WHERE culture_workflow_type IS NOT NULL AND opens_microbiology_case=false;
-- Merge only exact duplicate Program semantics; preserve every questionnaire response. UPDATE clinlims.program_sample ps SET program_id=m.canonical_id FROM amr_program_canonical m WHERE ps.program_id=m.id AND m.id<>m.canonical_id; UPDATE clinlims.micro_case c SET program_id=m.canonical_id FROM amr_program_canonical m WHERE c.program_id=m.id AND m.id<>m.canonical_id; DELETE FROM clinlims.program_lab_unit u USING amr_program_canonical m WHERE u.program_id=m.id AND m.id<>m.canonical_id; DELETE FROM clinlims.program p USING amr_program_canonical m WHERE p.id=m.id AND m.id<>m.canonical_id;
UPDATE clinlims.program SET show_on_micro_case=true WHERE id IN (SELECT program_id FROM amr_case_map);
-- Correct the old Bacteriology Program routing metadata only when test routing identifies one unit. UPDATE clinlims.program p SET test_section_id=units.id FROM (SELECT c.program_id,min(c.lab_unit_id) id FROM clinlims.micro_case c GROUP BY c.program_id HAVING count(DISTINCT c.lab_unit_id)=1) units WHERE p.id=units.program_id AND upper(trim(p.code))='BACTERIOLOGY'; DELETE FROM clinlims.program_lab_unit u USING clinlims.program p WHERE u.program_id=p.id AND upper(trim(p.code))='BACTERIOLOGY' AND u.test_section_id<>p.test_section_id AND EXISTS (SELECT 1 FROM clinlims.micro_case c WHERE c.program_id=p.id) AND NOT EXISTS (SELECT 1 FROM clinlims.micro_case c WHERE c.program_id=p.id AND c.lab_unit_id<>p.test_section_id); INSERT INTO clinlims.program_lab_unit(program_id,test_section_id) SELECT p.id,p.test_section_id FROM clinlims.program p WHERE upper(trim(p.code))='BACTERIOLOGY' AND p.test_section_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM clinlims.program_lab_unit u WHERE u.program_id=p.id AND u.test_section_id=p.test_section_id);
INSERT INTO clinlims.micro_case_activity(id,case_id,activity_type,occurred_at,performed_by,note,structured_data) SELECT md5('M8-group-'||c.id),c.id,'MIGRATION_REVIEW',now(),NULL, 'Existing cases share a V2 grouping key and remain independent; administrator review required', json_build_object('reason','SHARED_GROUPING','orderId',c.sample_id,'sampleTypeId',c.sample_type_id,'labUnitId',c.lab_unit_id,'siteId',c.site_id)::text FROM clinlims.micro_case c WHERE EXISTS (SELECT 1 FROM clinlims.micro_case sibling WHERE sibling.id<>c.id AND sibling.sample_id=c.sample_id AND sibling.sample_type_id=c.sample_type_id AND sibling.lab_unit_id=c.lab_unit_id AND sibling.site_id IS NOT DISTINCT FROM c.site_id);
INSERT INTO clinlims.micro_case_activity(id,case_id,activity_type,occurred_at,performed_by,note,structured_data) SELECT md5('M8-history-'||a.id),a.case_id,'LEGACY_HISTORY_PRESERVED',a.occurred_at,a.performed_by, replace(initcap(replace(a.activity_type,'_',' ')),'Culture Protocol','Culture protocol') || ': ' || coalesce(a.note,'') || CASE WHEN a.structured_data IS NULL THEN '' ELSE ' — '||a.structured_data END, json_build_object('originalActivityId',a.id,'originalEvent',a.activity_type,'originalData',a.structured_data)::text FROM clinlims.micro_case_activity a WHERE a.activity_type IN ('WORKFLOW_CHANGED','CULTURE_PROTOCOL_CHANGED','CULTURE_PURPOSE_CHANGED');
INSERT INTO clinlims.micro_case_activity(id,case_id,activity_type,occurred_at,performed_by,note,structured_data) SELECT md5('M8-protocol-'||c.id||'-'||setup.id),c.id,'LEGACY_HISTORY_PRESERVED',c.created_at,CASE WHEN c.created_by ~ '^[0-9]+$' THEN c.created_by::numeric END, 'Retired culture protocol: '||setup.name,to_jsonb(setup)::text FROM clinlims.micro_case c JOIN clinlims.micro_culture_setup setup ON setup.method_id=c.culture_method_id AND setup.workflow_type=c.workflow_type;

INSERT INTO clinlims.micro_legacy_migration_archive(id,source_table,source_id,content)
SELECT md5('setup-'||id),'micro_culture_setup',id,to_jsonb(s)::text FROM clinlims.micro_culture_setup s;
INSERT INTO clinlims.micro_legacy_migration_archive(id,source_table,source_id,content)
SELECT md5('case-'||id),'micro_case',id,json_build_object('workflowType',workflow_type,'createdBy',created_by)::text
FROM clinlims.micro_case WHERE workflow_type IS NOT NULL;
INSERT INTO clinlims.micro_legacy_migration_archive(id,source_table,source_id,content)
SELECT md5('test-'||id),'test',id::text,json_build_object('cultureWorkflowType',culture_workflow_type)::text
FROM clinlims.test WHERE culture_workflow_type IS NOT NULL;
INSERT INTO clinlims.micro_legacy_migration_archive(id,source_table,source_id,content)
SELECT md5('panel-'||id),'micro_ast_panel',id,json_build_object('workflowType',workflow_type)::text
FROM clinlims.micro_ast_panel WHERE workflow_type IS NOT NULL;

rollback.sql:
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM clinlims.micro_case)
       OR EXISTS (SELECT 1 FROM clinlims.micro_legacy_migration_archive)
       OR EXISTS (SELECT 1 FROM clinlims.program WHERE reporting_track_id IS NOT NULL)
       OR EXISTS (SELECT 1 FROM clinlims.sample WHERE microbiology_replicate_count IS NOT NULL) THEN
        RAISE EXCEPTION 'Environmental case context must be preserved before rollback';
    END IF;
END $$;
